INSERT OR IGNORE INTO recipe_steps (recipe_id, position, content) VALUES
('00000000-0000-4000-8000-000000000051', 1, 'Lave e corte os tomates e o pepino em pedaços uniformes.'),
('00000000-0000-4000-8000-000000000051', 2, 'Misture em uma tigela com as azeitonas e tempere com o azeite, o limão e o oregano.'),
('00000000-0000-4000-8000-000000000051', 3, 'Sirva imediatamente em duas porções ou conserve por até 1 dia na geladeira.'),
('00000000-0000-4000-8000-000000000052', 1, 'Refogue a cebola em manteiga até ficar translúcida.'),
('00000000-0000-4000-8000-000000000052', 2, 'Adicione o arroz e mexa até absorver o sabor do refogado.'),
('00000000-0000-4000-8000-000000000052', 3, 'Inclua a abóbora aos poucos com o caldo, mexendo até o arroz ficar cremoso.'),
('00000000-0000-4000-8000-000000000052', 4, 'Finalize com parmesão e sirva em porções quentes.'),
('00000000-0000-4000-8000-000000000053', 1, 'Tempere o frango com cominho e cozinhe em fogo médio até ficar macio.'),
